// utils/strategies/{strategy}/{Strategy}Strategies.ts
// Strategy — famille d'algorithmes interchangeables pour {Strategy}

// Interface commune — toutes les stratégies l'implémentent
export interface {Strategy}Strategy<TInput = unknown, TOutput = unknown> {
  execute(input: TInput): TOutput
}

// Stratégies concrètes — une par algorithme
export class {Strategy}StrategyA implements {Strategy}Strategy {
  execute(input: unknown): unknown {
    // Ajoute ici l'algorithme A
    // Exemple tri par date : return [...items].sort((a, b) => ...)
    return input
  }
}

export class {Strategy}StrategyB implements {Strategy}Strategy {
  execute(input: unknown): unknown {
    // Ajoute ici l'algorithme B
    // Exemple tri par titre : return [...items].sort((a, b) => ...)
    return input
  }
}

export class {Strategy}StrategyC implements {Strategy}Strategy {
  // Stratégie paramétrée — l'état extrinsèque est passé au constructeur
  constructor(private readonly param: unknown) {}

  execute(input: unknown): unknown {
    // Ajoute ici l'algorithme C utilisant this.param
    return input
  }
}

// Contexte — utilise la stratégie active, peut la changer à l'exécution
export class {Strategy}Context {
  constructor(private strategy: {Strategy}Strategy) {}

  setStrategy(strategy: {Strategy}Strategy): void {
    this.strategy = strategy
  }

  execute(input: unknown): unknown {
    return this.strategy.execute(input)
  }
}

// composables/{strategy}/use{Strategy}Strategy.ts
import {
  {Strategy}Context,
  {Strategy}StrategyA,
  {Strategy}StrategyB,
  {Strategy}StrategyC
} from '~/utils/strategies/{strategy}/{Strategy}Strategies'

export type {Strategy}StrategyName = 'strategyA' | 'strategyB' | 'strategyC'

export const use{Strategy}Strategy = () => {
  const activeStrategy = ref<{Strategy}StrategyName>('strategyA')
  const context = new {Strategy}Context(new {Strategy}StrategyA())

  const setStrategy = (name: {Strategy}StrategyName, param?: unknown) => {
    const strategies: Record<{Strategy}StrategyName, () => InstanceType<typeof {Strategy}StrategyA>> = {
      strategyA: () => new {Strategy}StrategyA(),
      strategyB: () => new {Strategy}StrategyB(),
      strategyC: () => new {Strategy}StrategyC(param),
    }
    context.setStrategy(strategies[name]())
    activeStrategy.value = name
  }

  const apply = (input: unknown) => context.execute(input)

  return { activeStrategy: readonly(activeStrategy), setStrategy, apply }
}

// tests/utils/strategies/{strategy}/{Strategy}Strategies.spec.ts
import { describe, it, expect } from 'vitest'
import {
  {Strategy}Context,
  {Strategy}StrategyA,
  {Strategy}StrategyB
} from '~/utils/strategies/{strategy}/{Strategy}Strategies'

describe('{Strategy}Strategies', () => {

  it('{Strategy}StrategyA.execute() retourne un résultat', () => {
    const strategy = new {Strategy}StrategyA()
    const result   = strategy.execute('input')
    expect(result).toBeDefined()
  })

  it('{Strategy}StrategyB.execute() retourne un résultat différent de A', () => {
    const input = [{ title: 'B' }, { title: 'A' }]
    const resultA = new {Strategy}StrategyA().execute(input)
    const resultB = new {Strategy}StrategyB().execute(input)
    // Les deux stratégies produisent des résultats (potentiellement différents)
    expect(resultA).toBeDefined()
    expect(resultB).toBeDefined()
  })

  describe('{Strategy}Context', () => {
    it('utilise la stratégie active', () => {
      const context = new {Strategy}Context(new {Strategy}StrategyA())
      expect(context.execute('input')).toBeDefined()
    })

    it('setStrategy() change la stratégie à l\'exécution', () => {
      const context = new {Strategy}Context(new {Strategy}StrategyA())
      context.setStrategy(new {Strategy}StrategyB())
      expect(context.execute('input')).toBeDefined()
    })
  })

})
